   201→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   202→    var inp = document.getElementById(wid + "-inp");
   203→    var btn = document.getElementById(wid + "-btn");
   204→    var res = document.getElementById(wid + "-res");
   205→    var btnLabel = cfg.buttonText;
   206→    if (!inp || !btn || !res) return;
   207→
   208→    function checkZip() {
   209→      var zip = inp.value.trim();
   210→      if (!zip) { inp.focus(); return; }
   211→
   212→      btn.disabled = true;
   213→      btn.textContent = "\u2026";
   214→      res.innerHTML = "";
   215→
   216→      fetch(
   217→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   218→          "&zip=" + encodeURIComponent(zip)
   219→      )
   220→        .then(function (r) { return r.json(); })
   221→        .then(function (data) {
   222→          btn.disabled = false;
   223→          btn.textContent = btnLabel;
   224→
   225→          if (data.allowed) {
   226→            var html = '<div class="zcc-result ok">' + esc(data.message);
   227→            if (cfg.showEta && data.eta) {
   228→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   229→            }
   230→            if (cfg.showZone && data.zone) {
   231→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   232→            }
   233→            html += "</div>";
   234→            res.innerHTML = html;
   235→          } else {
   236→            var html = '<div class="zcc-result fail">' + esc(data.message);
   237→            if (cfg.showWaitlistOnFailure) {
   238→              html +=
   239→                '<div class="zcc-wl">' +
   240→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
   241→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
   242→                "</div>";
   243→            }
   244→            html += "</div>";
   245→            res.innerHTML = html;
   246→
   247→            if (cfg.showWaitlistOnFailure) {
   248→              var wBtn = document.getElementById(wid + "-wl-btn");
   249→              if (wBtn) {
   250→                wBtn.addEventListener("click", function () {
   251→                  var emailEl = document.getElementById(wid + "-wl-email");
   252→                  var email = emailEl ? emailEl.value.trim() : "";
   253→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   254→                  joinWaitlist(zip, email, wBtn);
   255→                });
   256→              }
   257→            }
   258→          }
   259→        })
   260→        .catch(function () {
   261→          btn.disabled = false;
   262→          btn.textContent = btnLabel;
   263→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   264→        });
   265→    }
   266→
   267→    btn.addEventListener("click", checkZip);
   268→    inp.addEventListener("keydown", function (e) {
   269→      if (e.key === "Enter") checkZip();
   270→    });
   271→  }
