   289→            "</p>";
   290→        } else {
   291→          wBtn.disabled = false;
   292→          wBtn.textContent = "Join Waitlist";
   293→        }
   294→      })
   295→      .catch(function () {
   296→        wBtn.disabled = false;
   297→        wBtn.textContent = "Join Waitlist";
   298→      });
   299→  }
